const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Leaked constraints from abandoned branch: a@2 needs c@2 (missing); a@1 must succeed.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
  c: { '1.0.0': {} },
}, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// Backtrack across earlier choice: b's constraint on a forces a@1.
assert.deepEqual(resolve({
  a: { '2.0.0': {}, '1.0.0': {} },
  b: { '1.0.0': { a: '1.0.0' } },
}, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0' });

// Cycle.
assert.deepEqual(resolve({
  x: { '1.0.0': { y: '^1.0.0' } },
  y: { '1.2.0': { x: '1.0.0' } },
}, { x: '*' }), { x: '1.0.0', y: '1.2.0' });

// Long chain (beyond old 4096 cap and call-stack depth).
const n = 20000;
const reg = {};
for (let i = 0; i < n; i += 1) reg['p' + i] = { '1.0.0': i + 1 < n ? { ['p' + (i + 1)]: '1.0.0' } : {} };
const out = resolve(reg, { p0: '*' });
assert.equal(Object.keys(out).length, n);

// Unsatisfiable / missing.
assert.equal(resolve({ a: { '1.0.0': {} } }, { a: '2.0.0' }), null);
assert.equal(resolve({}, { a: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

