'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Leaked constraints from abandoned branch: a@2 needs c@2 (missing); a@1 must succeed.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
  c: { '1.0.0': {} },
}, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// Backtrack across earlier choice: b's constraint on a forces a@1.
assert.deepEqual(resolve({
  a: { '2.0.0': {}, '1.0.0': {} },
  b: { '1.0.0': { a: '1.0.0' } },
}, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0' });

// Cycle.
assert.deepEqual(resolve({
  x: { '1.0.0': { y: '^1.0.0' } },
  y: { '1.2.0': { x: '1.0.0' } },
}, { x: '*' }), { x: '1.0.0', y: '1.2.0' });

// Long chain (beyond old 4096 cap and call-stack depth).
const n = 20000;
const reg = {};
for (let i = 0; i < n; i += 1) reg['p' + i] = { '1.0.0': i + 1 < n ? { ['p' + (i + 1)]: '1.0.0' } : {} };
const out = resolve(reg, { p0: '*' });
assert.equal(Object.keys(out).length, n);

// Unsatisfiable / missing.
assert.equal(resolve({ a: { '1.0.0': {} } }, { a: '2.0.0' }), null);
assert.equal(resolve({}, { a: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Eager validation of unreachable entries.
assert.throws(() => resolve({ z: { '1.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ z: { '1.0.0': { q: '^bad' } } }, {}), TypeError);

// Caret rules.
assert.equal(satisfies('0.3.5', '^0.3.1'), true);
assert.equal(satisfies('0.4.0', '^0.3.1'), false);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('1.9.9', '^1.2.0'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// First-found rule: highest a picked first, then b adapts.
assert.deepEqual(resolve({
  a: { '2.0.0': { b: '<=2.0.0' }, '1.0.0': {} },
  b: { '3.0.0': {}, '2.0.0': {}, '1.0.0': {} },
}, { a: '*', b: '*' }), { a: '2.0.0', b: '2.0.0' });
